// do executes an HTTP request. headerOverrides, when non-nil, override global
// RequiredHeaders for this specific request (used for per-endpoint API versioning).
func (c *Client) do(ctx context.Context, method, path string, params map[string]string, body any, headerOverrides map[string]string) (json.RawMessage, int, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	targetURL := c.BaseURL + path

	var bodyBytes []byte
	if body != nil {
		b, err := json.Marshal(body)
		if err != nil {
			return nil, 0, fmt.Errorf("marshaling body: %w", err)
		}
		bodyBytes = b
	}

	// Resolve auth material before the dry-run branch so --dry-run can preview
	// exactly what would be sent. Uses only cached credentials; a token that
	// requires a network refresh will be re-fetched on the live request path,
	// not during dry-run.
	authHeader, err := c.authHeader(ctx)
	if err != nil {
		return nil, 0, err
	}

	// Build the request for dry-run display or actual execution
	if c.DryRun {
		return c.dryRun(method, targetURL, path, params, bodyBytes, headerOverrides, authHeader)
	}

	const maxRetries = 3
	var lastErr error

	for attempt := 0; attempt <= maxRetries; attempt++ {
		// Proactive rate limiting — wait before sending
		c.limiter.Wait()
		var bodyReader io.Reader
		if bodyBytes != nil {
			bodyReader = strings.NewReader(string(bodyBytes))
		}

		req, err := http.NewRequestWithContext(ctx, method, targetURL, bodyReader)
		if err != nil {
			return nil, 0, fmt.Errorf("creating request: %w", err)
		}
		if bodyBytes != nil {
			req.Header.Set("Content-Type", "application/json")
		}

		if params != nil {
			q := req.URL.Query()
			for k, v := range params {
				if v != "" {
					q.Set(k, v)
				}
			}
			req.URL.RawQuery = q.Encode()
		}

		if authHeader != "" {
			req.Header.Set("Authorization", authHeader)
		}
		if c.Config != nil {
			for k, v := range c.Config.Headers {
				req.Header.Set(k, v)
			}
		}
		// Per-endpoint header overrides (e.g., different API version per resource)
		for k, v := range headerOverrides {
			req.Header.Set(k, v)
		}
		if req.Header.Get("User-Agent") == "" {
			req.Header.Set("User-Agent", "drivethrurpg-pp-cli/0.1.0")
		}

		resp, err := c.HTTPClient.Do(req)
		if err != nil {
			if ctxErr := ctx.Err(); ctxErr != nil {
				return nil, 0, ctxErr
			}
			lastErr = fmt.Errorf("%s %s: %s", method, path, c.redactErrorText(err))
			continue
		}

		respBody, err := io.ReadAll(resp.Body)
		resp.Body.Close()
		if err != nil {
			return nil, 0, fmt.Errorf("reading response: %w", err)
		}
		respBody = sanitizeJSONResponse(respBody)

		// Success
		if resp.StatusCode < 400 {
			c.limiter.OnSuccess()
			if method != http.MethodGet && !c.DryRun {
				c.invalidateCache()
			}
			return json.RawMessage(respBody), resp.StatusCode, nil
		}

		apiErr := &APIError{
			Method:     method,
			Path:       path,
			StatusCode: resp.StatusCode,
			Body:       truncateBody(respBody),
		}

		// Rate limited - adjust adaptive limiter and retry
		if resp.StatusCode == 429 && attempt < maxRetries {
			c.limiter.OnRateLimit()
			wait := cliutil.RetryAfter(resp)
			fmt.Fprintf(os.Stderr, "rate limited, waiting %s (attempt %d/%d, rate adjusted to %.1f req/s)\n", wait, attempt+1, maxRetries, c.limiter.Rate())
			time.Sleep(wait)
			lastErr = apiErr
			continue
		}

		// Server error - retry with backoff
		if resp.StatusCode >= 500 && attempt < maxRetries {
			wait := time.Duration(math.Pow(2, float64(attempt))) * time.Second
			fmt.Fprintf(os.Stderr, "server error %d, retrying in %s (attempt %d/%d)\n", resp.StatusCode, wait, attempt+1, maxRetries)
			time.Sleep(wait)
			lastErr = apiErr
			continue
		}

		// Client error or retries exhausted - return the error
		return nil, resp.StatusCode, apiErr
	}

	return nil, 0, lastErr
}

// dryRun prints the outgoing request exactly as the live path would send it,
// using the auth material already resolved in `do()`. Never triggers a network
// call — the caller is responsible for passing cached auth material only.
func (c *Client) dryRun(method, targetURL, path string, params map[string]string, body []byte, headerOverrides map[string]string, authHeader string) (json.RawMessage, int, error) {
	fmt.Fprintf(os.Stderr, "%s %s\n", method, targetURL)
	queryPrinted := false
	if params != nil {
		keys := make([]string, 0, len(params))
		for k := range params {
			if params[k] != "" {
				keys = append(keys, k)
			}
		}
		sort.Strings(keys)
		for _, k := range keys {
			sep := "?"
			if queryPrinted {
				sep = "&"
			}
			fmt.Fprintf(os.Stderr, "  %s%s=%s\n", sep, k, maskSensitiveParam(k, params[k]))
			queryPrinted = true
		}
	}
	_ = queryPrinted
	if body != nil {
		var pretty json.RawMessage
		if json.Unmarshal(body, &pretty) == nil {
			enc := json.NewEncoder(os.Stderr)
			enc.SetIndent("  ", "  ")
			fmt.Fprintf(os.Stderr, "  Body:\n")
			enc.Encode(pretty)
		}
	}
	if authHeader != "" {
		fmt.Fprintf(os.Stderr, "  %s: %s\n", "Authorization", maskToken(authHeader))
	}
	fmt.Fprintf(os.Stderr, "\n(dry run - no request sent)\n")
	preview := map[string]any{
		"dry_run": true,
		"method":  method,
		"path":    path,
		"url":     targetURL,
	}
	if len(params) > 0 {
		query := make(map[string]string, len(params))
		for k, v := range params {
			if v != "" {
				query[k] = maskSensitiveParam(k, v)
			}
		}
		if len(query) > 0 {
			preview["query"] = query
		}
	}
	if body != nil {
		preview["body"] = json.RawMessage(body)
	}
	if authHeader != "" || len(headerOverrides) > 0 {
		headers := map[string]string{}
		if authHeader != "" {
			headers["Authorization"] = maskToken(authHeader)
		}
		for k, v := range headerOverrides {
			headers[k] = maskToken(v)
		}
		preview["headers"] = headers
	}
	data, err := json.Marshal(preview)
	if err != nil {
		return nil, 0, fmt.Errorf("marshaling dry-run preview: %w", err)
	}
	return data, 0, nil
}

func (c *Client) ConfiguredTimeout() time.Duration {
	if c.HTTPClient != nil && c.HTTPClient.Timeout > 0 {
		return c.HTTPClient.Timeout
	}
	return 30 * time.Second
}

func (c *Client) authHeader(ctx context.Context) (string, error) {
	if c.Config == nil {
		return "", nil
	}
	if c.Config.AuthHeader() == "" && c.Config.ApplicationKey != "" {
		if c.DryRun {
			return "DRY_RUN_TOKEN_FROM_APPLICATION_KEY", nil
		}
		token, err := c.ExchangeApplicationKeyContext(ctx, c.Config.ApplicationKey)
		if err != nil {
			return "", err
		}
		c.Config.DrivethrurpgDtrpgToken = token.Token
		c.Config.RefreshToken = token.RefreshToken
	}
	return c.Config.AuthHeader(), nil
}

type ApplicationKeyToken struct {
	Token           string `json:"token"`
	RefreshToken    string `json:"refreshToken"`
	RefreshTokenTTL int    `json:"refreshTokenTTL"`
}

func (c *Client) ExchangeApplicationKey(applicationKey string) (*ApplicationKeyToken, error) {
	return c.ExchangeApplicationKeyContext(context.Background(), applicationKey)
}

func (c *Client) ExchangeApplicationKeyContext(ctx context.Context, applicationKey string) (*ApplicationKeyToken, error) {
	if strings.TrimSpace(applicationKey) == "" {
		return nil, fmt.Errorf("DriveThruRPG application key is empty")
	}
	if ctx == nil {
		ctx = context.Background()
	}
	endpoint, err := url.Parse(c.BaseURL + "/auth_key")
	if err != nil {
		return nil, fmt.Errorf("building auth URL: %w", err)
	}
	q := endpoint.Query()
	q.Set("applicationKey", applicationKey)
	endpoint.RawQuery = q.Encode()

	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint.String(), nil)
	if err != nil {
		return nil, fmt.Errorf("creating auth request: %w", err)
	}
	req.Header.Set("Accept", "application/json")
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("User-Agent", "drivethrurpg-pp-cli/0.1.0")

	resp, err := c.HTTPClient.Do(req)
	if err != nil {
		if ctxErr := ctx.Err(); ctxErr != nil {
			return nil, ctxErr
		}
		return nil, fmt.Errorf("POST /auth_key: %s", c.redactErrorText(err))
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("reading auth response: %w", err)
	}
	body = sanitizeJSONResponse(body)
	if resp.StatusCode >= 400 {
		return nil, &APIError{
			Method:     http.MethodPost,
			Path:       "/auth_key",
			StatusCode: resp.StatusCode,
			Body:       truncateBody(body),
		}
	}

	var token ApplicationKeyToken
	if err := json.Unmarshal(body, &token); err != nil {
		return nil, fmt.Errorf("parsing auth response: %w", err)
	}
	if token.Token == "" {
		return nil, fmt.Errorf("auth response did not include a token")
	}
	return &token, nil
}

// sanitizeJSONResponse strips known JSONP/XSSI prefixes and UTF-8 BOM from
// response bodies so that downstream JSON parsing succeeds. For clean JSON
// responses these checks are no-ops.
func sanitizeJSONResponse(body []byte) []byte {
	// UTF-8 BOM
	body = bytes.TrimPrefix(body, []byte("\xEF\xBB\xBF"))

	// JSONP/XSSI prefixes, ordered longest-first where prefixes overlap
	prefixes := [][]byte{
		[]byte(")]}'\n"),
		[]byte(")]}'"),
		[]byte("{}&&"),
		[]byte("for(;;);"),
		[]byte("while(1);"),
	}
	for _, p := range prefixes {
		if bytes.HasPrefix(body, p) {
			body = bytes.TrimPrefix(body, p)
			body = bytes.TrimLeft(body, " \t\r\n")
			break
		}
	}
	return body
}

// maskToken redacts all but the last 4 characters of a token for safe display.
func maskToken(token string) string {
	if token == "" {
		return ""
	}
	if len(token) <= 4 {
		return "****"
	}
	return "****" + token[len(token)-4:]
}

func maskSensitiveParam(name, value string) string {
	lower := strings.ToLower(name)
	for _, marker := range []string{"applicationkey", "authorization", "password", "secret", "token", "apikey", "api_key", "key"} {
		if strings.Contains(lower, marker) {
			return maskToken(value)
		}
	}
	return value
}

var sensitiveQueryValueRE = regexp.MustCompile(`(?i)([?&][^=\s"'&]*(?:applicationkey|authorization|password|secret|token|apikey|api_key|key)[^=\s"'&]*=)([^&\s"']+)`)

func (c *Client) redactErrorText(err error) string {
	if err == nil {
		return ""
	}
	msg := redactSensitiveText(err.Error())
	if c.Config == nil {
		return msg
	}
	for _, secret := range []string{
		c.Config.ApplicationKey,
		c.Config.DrivethrurpgDtrpgToken,
		c.Config.AccessToken,
		c.Config.RefreshToken,
		c.Config.ClientSecret,
	} {
		if secret != "" {
			msg = strings.ReplaceAll(msg, secret, maskToken(secret))
		}
	}
	return msg
}

func redactSensitiveText(s string) string {
	return sensitiveQueryValueRE.ReplaceAllStringFunc(s, func(match string) string {
		parts := strings.SplitN(match, "=", 2)
		if len(parts) != 2 {
			return match
		}
		value := parts[1]
		if unescaped, err := url.QueryUnescape(value); err == nil {
			value = unescaped
		}
		return parts[0] + "=" + maskToken(value)
	})
}

func truncateBody(b []byte) string {
	s := redactSensitiveText(string(b))
	if len(s) > 200 {
		return s[:200] + "..."
	}
	return s
}
